Use Node’s built-in `http.request()` with `socketPath`. A Unix-socket request uses `socketPath` instead of `host`/`port`; the request path and headers are sent to the HTTP server listening on that socket.

```js
const http = require('node:http');

const proxy = http.createServer((req, res) => {
  const upstream = http.request(
    {
      socketPath: '/tmp/upstream.sock',
      method: req.method,
      path: req.url,
      headers: req.headers,
    },
    (upstreamRes) => {
      res.writeHead(upstreamRes.statusCode, upstreamRes.headers);
      upstreamRes.pipe(res);
    }
  );

  upstream.on('error', (err) => {
    res.statusCode = 502;
    res.end(err.message);
  });

  req.pipe(upstream);
});

proxy.listen('/tmp/proxy.sock');
```

For a direct request to a Unix-domain-socket HTTP server:

```js
const req = http.request(
  {
    socketPath: '/tmp/example.sock',
    path: '/',
  },
  (res) => {
    res.pipe(process.stdout);
  }
);

req.end();
```

Node’s environment/global proxy settings are ignored when the request is made to a Unix-domain socket.
